import numpy as np
import pandas as pd
from datetime import datetime
import pytz

def r_as_POSIXct(x, tz="", *args, **kwargs):
    """
    Python reproduction of R's as.POSIXct.
    """
    # Handle case where x is already a POSIXct-like object
    if isinstance(x, (pd.Timestamp, pd.DatetimeIndex)):
        if tz == "":
            return x
        if isinstance(x, pd.Timestamp):
            return x.tz_localize(None).tz_localize(tz) if x.tz is None else x.tz_convert(tz)
        return x.tz_localize(None).tz_localize(tz) if x.tz is None else x.tz_convert(tz)

    if x is None:
        return np.array([], dtype='datetime64[ns]')

    # Handle logical/numeric NAs
    if isinstance(x, np.ndarray) and np.issubdtype(x.dtype, np.bool_):
        if np.all(pd.isna(x)):
            return pd.to_datetime(x.astype(float), unit='s')

    # Detect scalar versus sequence
    is_scalar = isinstance(x, (str, int, float, np.integer, np.floating))

    if is_scalar:
        x_input = [x]
    elif isinstance(x, (list, np.ndarray, pd.Series)):
        x_input = x
    else:
        try:
            x_input = list(x)
        except TypeError:
            x_input = [x]
            is_scalar = True

    # R's as.POSIXct behavior for numeric types:
    # If numeric, it's treated as seconds since 1970-01-01.
    # We must check if the input is numeric before using pd.to_datetime strings.
    input_is_numeric = False
    if isinstance(x_input, (list, np.ndarray, pd.Series)):
        # Check if the first non-NaN element is numeric
        flat_x = np.array(x_input, dtype=object)
        non_na = flat_x[~pd.isna(flat_x)]
        if len(non_na) > 0 and isinstance(non_na[0], (int, float, np.integer, np.floating)):
            input_is_numeric = True
    elif isinstance(x_input, (int, float, np.integer, np.floating)):
        input_is_numeric = True

    if input_is_numeric:
        # R's numeric conversion to POSIXct is seconds since epoch
        s = pd.to_datetime(np.array(x_input, dtype=float), unit='s')
    else:
        # String/Factor conversion
        # R's as.POSIXct calls as.POSIXlt which handles timezone
        s = pd.to_datetime(x_input, errors='coerce')
        if tz != "":
            # If tz is provided and we have strings, we localize them
            # Note: pd.to_datetime often assumes UTC or naive. 
            # R interprets the string as being in that tz.
            if isinstance(s, pd.DatetimeIndex):
                s = s.tz_localize(tz, ambiguous='infer').tz_convert(None)
            else:
                s = s.tz_localize(tz, ambiguous='infer').tz_convert(None)

    # Final output formatting to match R's POSIXct (which the harness sees as a list of timestamps/nulls)
    if is_scalar:
        res = s[0] if isinstance(s, pd.DatetimeIndex) else s
        return res if pd.notna(res) else None

    if isinstance(s, pd.DatetimeIndex):
        # Return a numpy array of objects where NaT is converted to None to match "null" in harness
        out = s.to_numpy(dtype=object)
        mask = pd.isna(out)
        out[mask] = None
        return out

    return np.array([s], dtype=object)
